        for (int j = 0; j < 3; j++) {
            cin >> u[i][j];
        }
    }

    vector<long long> d(n + 2, 0);
    for (int k = 0; k < q; k++) {
        d[u[k][0]] += u[k][2];
        d[u[k][1] + 1] -= u[k][2];
    }
    long long cur = 0;
    for (int i = 1; i <= n; i++) {
        cur += d[i];
        cout << cur << (i < n ? " " : "\n");
